contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: try sending an arbitrary amount to c.go
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to send");

        // observe owner and c balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balCBefore = address(c).balance;

        bool reverted;
        // make the state-changing call on c as a top-level statement
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-call values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balCAfter = address(c).balance;

        // General rule: c.owner is never changed by go; additionally, if the call did not revert
        // then c's balance becomes zero.
        assert(ownerAfter == ownerBefore && (reverted || balCAfter == 0));
    }

    receive() external payable {}
}

